<nav class="analytics-tabs" aria-label="Analytics sections"><a href="<?= e_attr($basePath) ?>/admin/analytics">Dashboard</a><a class="active" href="<?= e_attr($basePath) ?>/admin/analytics/visitors">Visitor Explorer</a><a href="<?= e_attr($basePath) ?>/admin/analytics/geography">Audience locations</a></nav>
<section class="card"><div class="card-heading"><div><p class="section-kicker">Anonymous sessions</p><h2>Visitor Explorer</h2><p class="card-subtitle">Follow aggregate visitor journeys without names, raw IP addresses, or full user-agent strings.</p></div><span class="badge neutral"><?= (int)$data['total'] ?> visits</span></div><form class="analytics-filter" method="get" action="<?= e_attr($siteBasePath) ?>/index.php"><input type="hidden" name="p" value="/admin/analytics/visitors"><label>From<input type="date" name="from" value="<?= e_attr($data['from']) ?>"></label><label>To<input type="date" name="to" value="<?= e_attr($data['to']) ?>"></label><label>Channel<input name="channel" value="<?= e_attr($filters['channel']) ?>" placeholder="Any"></label><label>Device<input name="device_family" value="<?= e_attr($filters['device_family']) ?>" placeholder="Any"></label><label>Status<select name="status"><option value="">Any</option><option value="live" <?= $filters['status']==='live'?'selected':'' ?>>Live</option><option value="completed" <?= $filters['status']==='completed'?'selected':'' ?>>Completed</option></select></label><label>Country<input name="country_name" value="<?= e_attr($filters['country_name']) ?>" placeholder="Any"></label><label>Browser<input name="browser_family" value="<?= e_attr($filters['browser_family']) ?>" placeholder="Any"></label><label>Operating system<input name="os_family" value="<?= e_attr($filters['os_family']) ?>" placeholder="Any"></label><label>Referrer<input name="referrer_domain" value="<?= e_attr($filters['referrer_domain']) ?>" placeholder="Any"></label><label>Visited page<input name="page_path" value="<?= e_attr($filters['page_path']) ?>" placeholder="/services"></label><button class="btn">Filter</button></form></section>
<section class="visitor-list"><?php if(!$data['rows']): ?><div class="card empty-state"><strong>No matching visits</strong><span>Try a wider date range or clear a filter.</span></div><?php endif; ?><?php foreach($data['rows'] as $visit): ?><details class="visitor-card"><summary><span class="visitor-device"><?= e(substr($visit['device_family'],0,1)) ?></span><span><strong><?= e($visit['channel']) ?> visit</strong><small><?= e($visit['country_name']?:'Unknown location') ?> · <?= e($visit['device_family']) ?> · <?= e($visit['browser_family']) ?></small></span><span><strong><?= (int)$visit['page_count'] ?> pages</strong><small><?= gmdate('i:s',(int)$visit['active_seconds']) ?> active</small></span><time><?= e(date('M j, g:i a',strtotime($visit['started_at']))) ?></time></summary><div class="visitor-detail"><dl><div><dt>Referrer</dt><dd><?= e($visit['referrer_domain']?:'Direct / not supplied') ?></dd></div><div><dt>Campaign</dt><dd><?= e($visit['utm_campaign']?:'Not supplied') ?></dd></div><div><dt>System</dt><dd><?= e($visit['os_family']) ?></dd></div><div><dt>Last seen</dt><dd><?= e($visit['last_seen_at']) ?> UTC</dd></div></dl><h3>Page journey</h3><ol class="journey"><?php foreach($visit['journey'] as $step): ?><li><span><strong><?= e($step['page_title']?:$step['page_path']) ?></strong><small><?= e($step['page_path']) ?></small></span><span><?= gmdate('i:s',(int)$step['active_seconds']) ?> active</span></li><?php endforeach; ?></ol></div></details><?php endforeach; ?></section>
<?php $pages=max(1,(int)ceil($data['total']/25));$pageQuery=['from'=>$data['from'],'to'=>$data['to']]+array_filter($filters,fn($v)=>$v!=='');if($pages>1): ?><nav class="pagination" aria-label="Visitor pages"><?php for($p=1;$p<=$pages;$p++): ?><a class="<?= $p===$data['page']?'active':'' ?>" href="<?= e_attr($basePath) ?>/admin/analytics/visitors&<?= e_attr(http_build_query($pageQuery+['page'=>$p],'','&',PHP_QUERY_RFC3986)) ?>"><?= $p ?></a><?php endfor; ?></nav><?php endif; ?>
